    const sp = () => (r.bool(0.25) ? " " : "");
    let cur = r.int(0, hi), s = sp() + cur, count = 1;
    while (big ? s.length < 290000 : count < terms) {
      let op = r.pick(["+", "-", "*", "/"]), x = r.int(0, hi);
      if (op === "*" && cur * x > cap) op = "/"; // keep every product small
      if (op === "/" && x === 0) x = r.int(1, hi);
      cur = op === "+" || op === "-" ? x : op === "*" ? cur * x : Math.trunc(cur / x);
      s += sp() + op + sp() + x;
      count++;
    }
    return [s + sp()];
