function calculate(s: string): number {
  const terms: number[] = [];
  let num = 0, op = "+";
  for (let i = 0; i <= s.length; i++) {
    const c = i < s.length ? s[i] : "+"; // sentinel applies the last number
    if (c === " ") continue;
    if (c >= "0" && c <= "9") {
      num = num * 10 + (c.charCodeAt(0) - 48);
      continue;
    }
    if (op === "+") terms.push(num);
    else if (op === "-") terms.push(-num);
    else if (op === "*") terms.push(terms.pop()! * num);
    else terms.push(Math.trunc(terms.pop()! / num));
    op = c;
    num = 0;
  }
  let total = 0;
  for (const t of terms) total += t;
  return total;
}

