class Solution:
    def calculate(self, s: str) -> int:
        terms = []
        num, op = 0, "+"
        for c in s + "+":  # sentinel applies the last number
            if c == " ":
                continue
            if c.isdigit():
                num = num * 10 + ord(c) - 48
                continue
            if op == "+":
                terms.append(num)
            elif op == "-":
                terms.append(-num)
            elif op == "*":
                terms.append(terms.pop() * num)
            else:
                top = terms.pop()
                q = abs(top) // num  # num is never negative; truncate toward zero
                terms.append(-q if top < 0 else q)
            op, num = c, 0
        return sum(terms)

